'use strict';

function showWorkbookFormatCells(c){
  if(!validWorkbookContext(c,true)||c.state.saving)return;
  const style=contextStyle(c),sheet=c.state.book.sheets[c.index],edits=c.state.edits;
  const initial={fontName:style.fontName||'Arial',fontSize:Math.round((style.fontSize||11)*2)/2,bold:!!style.bold,italic:!!style.italic,underline:!!style.underline,strike:!!style.strike,color:(style.color||'#000000').toLowerCase(),horizontal:style.horizontal||'left',vertical:style.vertical||'top',wrap:!!style.wrap,numFmt:Number(style.numFmt)||0};
  const initialFill=(style.background||'none').toLowerCase();let address=contextAddress(c),area=WorkbookFormat.range(sheet,address);
  const selectedMerge=c.axis==='cell'&&area.first.row===area.last.row&&area.first.column===area.last.column&&sheet.merges.find(m=>m.start===address);
  if(selectedMerge){address=selectedMerge.start+':'+XlsxPackage.address(selectedMerge.last.column,selectedMerge.last.row);area=WorkbookFormat.range(sheet,address);}
  const merged=sheet.merges.some(m=>m.first.row===area.first.row&&m.first.column===area.first.column&&m.last.row===area.last.row&&m.last.column===area.last.column);
  const canMerge=c.axis==='cell'&&(merged||area.first.row!==area.last.row||area.first.column!==area.last.column);
  const fonts=[...new Set([...WorkbookFormat.fonts,...c.state.book.styles.map(s=>s.fontName).filter(Boolean)])];
  const numberFormats=[[0,'General'],[1,'Number — 0 decimal'],[2,'Number — 2 decimals'],[3,'Number — grouped'],[4,'Number — grouped, 2 decimals'],[5,'Currency (USD)'],[7,'Currency (USD) — 2 decimals'],[14,'Date'],[18,'Time'],[9,'Percentage — 0 decimal'],[10,'Percentage — 2 decimals'],[12,'Fraction — one digit'],[13,'Fraction — two digits'],[11,'Scientific'],[49,'Text']];
  if(!numberFormats.some(([id])=>id===initial.numFmt))numberFormats.push([initial.numFmt,'Format tersimpan']);
  const horizontal=[['left','Left'],['center','Center'],['right','Right']],vertical=[['top','Top'],['center','Center'],['bottom','Bottom']];
  if(!horizontal.some(([id])=>id===initial.horizontal))horizontal.push([initial.horizontal,'Format tersimpan']);
  if(!vertical.some(([id])=>id===initial.vertical))vertical.push([initial.vertical,'Format tersimpan']);
  const options=(items,value)=>items.map(([id,label])=>`<option value="${esc(String(id))}" ${String(value)===String(id)?'selected':''}>${esc(label)}</option>`).join('');
  const select=(id,label,name,items,value)=>`<label class="format-field" for="${id}"><span>${label}</span><select id="${id}" name="${name}" data-native-select>${options(items,value)}</select></label>`;
  const check=(id,name,label,value,disabled=false)=>`<label class="format-check"><input id="${id}" type="checkbox" name="${name}" ${value?'checked':''} ${disabled?'disabled':''}>${label}</label>`;
  const colors=['#ffffff','#000000','#e7e6e6','#44546a','#4472c4','#ed7d31','#a5a5a5','#ffc000','#5b9bd5','#70ad47','#f2f2f2','#d9e2f3','#dae3f3','#fce4d6','#e2f0d9','#fff2cc','#ff0000','#ffff00','#00b050','#00b0f0','#0070c0','#7030a0'];
  const borderNames={top:'Top',bottom:'Bottom',left:'Left',right:'Right',insideH:'Inside Horizontal',insideV:'Inside Vertical'};
  const borderDraft=Object.fromEntries(Object.keys(borderNames).map(side=>[side,style.borders?.[side]||null])),borderActions=[];
  const tabs=['Number','Alignment','Font','Border','Fill','Protection'];
  showModal(`${modalHeading('Format Cells')}<form id="context-cell-format" class="format-cells-form" novalidate><div role="tablist" aria-label="Format Cells" class="format-cells-tabs">${tabs.map((tab,i)=>`<button type="button" role="tab" id="format-tab-${tab.toLowerCase()}" aria-controls="format-panel-${tab.toLowerCase()}" aria-selected="${i===0}" tabindex="${i===0?'0':'-1'}">${tab}</button>`).join('')}</div>
    <section id="format-panel-number" role="tabpanel" aria-labelledby="format-tab-number" class="format-cells-panel"><div class="format-two-columns"><label class="format-field format-number-list" for="context-numFmt"><span>Category / Format</span><select id="context-numFmt" name="numFmt" size="7" data-native-select>${options(numberFormats,initial.numFmt)}</select></label><div class="format-sample"><span>Sample</span><output id="format-number-sample"></output><p class="small muted">Pilih format angka untuk melihat contohnya.</p></div></div></section>
    <section id="format-panel-alignment" role="tabpanel" aria-labelledby="format-tab-alignment" class="format-cells-panel" hidden><fieldset><legend>Text alignment</legend><div class="format-two-columns">${select('context-horizontal','Horizontal','horizontal',horizontal,initial.horizontal)}${select('context-vertical','Vertical','vertical',vertical,initial.vertical)}</div></fieldset><fieldset><legend>Text control</legend>${check('context-wrap','wrap','Wrap text',initial.wrap)}${check('format-merge','merge','Merge cells',merged,!canMerge)}</fieldset></section>
    <section id="format-panel-font" role="tabpanel" aria-labelledby="format-tab-font" class="format-cells-panel" hidden><div class="format-font-grid">${select('context-fontName','Font','fontName',fonts.map(font=>[font,font]),initial.fontName)}<label class="format-field" for="context-font-size"><span>Size</span><input id="context-font-size" name="fontSize" type="number" min="1" max="409" step="0.5" value="${initial.fontSize}"></label></div><fieldset><legend>Font style</legend><div class="format-check-row">${check('context-bold','bold','Bold',initial.bold)}${check('context-italic','italic','Italic',initial.italic)}${check('context-underline','underline','Underline',initial.underline)}${check('context-strike','strike','Strikethrough',initial.strike)}</div></fieldset><label class="format-field format-color" for="context-color"><span>Color</span><input id="context-color" name="color" type="color" value="${esc(initial.color)}"></label><div class="format-sample"><span>Preview</span><output id="format-font-sample">AaBbCcYyZz</output></div></section>
    <section id="format-panel-border" role="tabpanel" aria-labelledby="format-tab-border" class="format-cells-panel" hidden><div class="format-border-layout"><fieldset class="format-line-picker"><legend>Line style</legend><input type="hidden" id="format-border-style" name="borderStyle" value="thin"><div role="group" aria-label="Line styles" class="format-line-list">${WorkbookBorders.styles.map(([id,label])=>`<button type="button" data-format-border-style="${id}" aria-label="Line style ${esc(label)}" title="${esc(label)}" aria-pressed="${id==='thin'}"><i style="border-top:${borderLineCss(id,'#243b53')}"></i><span>${esc(label)}</span></button>`).join('')}</div><label class="format-field format-color" for="format-border-color"><span>Color</span><input id="format-border-color" name="borderColor" type="color" value="#000000"></label></fieldset><div><fieldset><legend>Presets</legend><div class="format-border-presets">${[['none','None'],['outside','Outline'],['inside','Inside'],['all','All']].map(([id,label])=>`<button type="button" data-format-border-preset="${id}" aria-label="Preset ${label}" aria-pressed="false">${label}</button>`).join('')}</div></fieldset><fieldset><legend>Border</legend><div id="format-border-preview" class="format-border-preview"><span>Text</span>${Object.entries(borderNames).map(([side,label])=>`<button type="button" class="format-border-edge format-edge-${side}" data-format-border-side="${side}" aria-label="Preview ${label} border" aria-pressed="false"><i></i></button>`).join('')}</div><div class="format-border-side-buttons">${Object.entries(borderNames).map(([side,label])=>`<button type="button" data-format-border-side="${side}" aria-label="${label} border" aria-pressed="false">${label}</button>`).join('')}</div></fieldset></div></div></section>
    <section id="format-panel-fill" role="tabpanel" aria-labelledby="format-tab-fill" class="format-cells-panel" hidden>${select('format-fill-mode','Background Color','fillMode',[['none','No Color'],['solid','Solid Color']],initialFill==='none'?'none':'solid')}<div class="format-color-palette" role="group" aria-label="Background Color">${colors.map(color=>`<button type="button" data-format-fill="${color}" style="--fill-color:${color}" aria-label="${color}" title="${color}"></button>`).join('')}</div><label class="format-field format-color" for="context-background"><span>More Colors</span><input id="context-background" name="background" type="color" value="${esc(initialFill==='none'?'#ffffff':initialFill)}"></label><div class="format-sample"><span>Sample</span><output id="format-fill-sample"></output></div></section>
    <section id="format-panel-protection" role="tabpanel" aria-labelledby="format-tab-protection" class="format-cells-panel" hidden><p>Pengaturan proteksi sel tersedia setelah perlindungan worksheet didukung.</p></section>
    <div id="context-format-error" class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn btn-secondary" data-action="close-modal">Batal</button><button type="submit" class="btn btn-primary">Terapkan Format</button></div></form>`,'format-cells-modal');
  const form=document.getElementById('context-cell-format'),controls=[...form.querySelectorAll('[role=tab]')];
  function activate(tab,focus=false){for(const button of controls){const selected=button===tab;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1;document.getElementById(button.getAttribute('aria-controls')).hidden=!selected;}if(focus)tab.focus();}
  for(const button of controls){button.onclick=()=>activate(button);button.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const index=controls.indexOf(button),next=event.key==='Home'?0:event.key==='End'?controls.length-1:(index+(event.key==='ArrowRight'?1:-1)+controls.length)%controls.length;activate(controls[next],true);};}
  function preview(){
    const data=new FormData(form),original=sheet.cells.get(c.state.selected),cell=original?.cloneNode(true)||sheet.xml.createElementNS(sheet.xml.documentElement.namespaceURI,'c'),fmt=Number(data.get('numFmt'));
    if(!original){const value=sheet.xml.createElementNS(sheet.xml.documentElement.namespaceURI,'v');value.textContent='1234.56';cell.appendChild(value);}cell.setAttribute('s','0');
    document.getElementById('format-number-sample').textContent=WorkbookFormat.display({...c.state.book,styles:[{numFmt:fmt}]},cell)||'—';
    const sample=document.getElementById('format-font-sample');Object.assign(sample.style,{fontFamily:String(data.get('fontName')),fontSize:Math.min(36,Math.max(8,Number(data.get('fontSize'))||11))+'pt',fontWeight:data.has('bold')?'700':'400',fontStyle:data.has('italic')?'italic':'normal',textDecoration:[data.has('underline')?'underline':'',data.has('strike')?'line-through':''].filter(Boolean).join(' ')||'none',color:String(data.get('color'))});
    document.getElementById('format-fill-sample').style.background=data.get('fillMode')==='none'?'transparent':String(data.get('background'));
    form.querySelectorAll('[data-format-border-style]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.formatBorderStyle===data.get('borderStyle'))));
    form.querySelectorAll('[data-format-border-side]').forEach(button=>{const side=button.dataset.formatBorderSide,on=Boolean(borderDraft[side]);button.setAttribute('aria-pressed',String(on));const line=button.querySelector('i');if(line)line.style[side==='left'||side==='right'||side==='insideV'?'borderLeft':'borderTop']=borderDraft[side]||'1px dotted #c2cad4';});
    for(const button of form.querySelectorAll('[data-format-border-preset]')){const outer=['top','bottom','left','right'],inner=['insideH','insideV'],preset=button.dataset.formatBorderPreset;button.setAttribute('aria-pressed',String(preset==='none'?!Object.values(borderDraft).some(Boolean):preset==='outside'?outer.every(side=>borderDraft[side]):preset==='inside'?inner.every(side=>borderDraft[side]):Object.values(borderDraft).every(Boolean)));}
  }
  form.addEventListener('input',preview);form.addEventListener('change',event=>{if(event.target.id==='context-background')form.elements.fillMode.value='solid';preview();});
  form.querySelectorAll('[data-format-fill]').forEach(button=>button.onclick=()=>{form.elements.background.value=button.dataset.formatFill;form.elements.fillMode.value='solid';preview();});preview();
  form.addEventListener('click',event=>{
    const line=event.target.closest('[data-format-border-style]'),side=event.target.closest('[data-format-border-side]'),preset=event.target.closest('[data-format-border-preset]');
    if(line){form.elements.borderStyle.value=line.dataset.formatBorderStyle;preview();return;}
    if(!side&&!preset)return;
    const lineStyle=form.elements.borderStyle.value,color=form.elements.borderColor.value,css=borderLineCss(lineStyle,color),options={lineStyle,color};
    if(side){const key=side.dataset.formatBorderSide,on=!borderDraft[key];borderDraft[key]=on?css:null;borderActions.push({preset:'custom',options:{...options,sides:{[key]:true},erase:!on,preserveUnselected:true}});}
    else {const id=preset.dataset.formatBorderPreset,outer=['top','bottom','left','right'],inner=['insideH','insideV'];if(id==='none'){for(const key of Object.keys(borderDraft))borderDraft[key]=null;borderActions.push({preset:'none',options});}else if(id==='inside'){for(const key of inner)borderDraft[key]=css;borderActions.push({preset:'custom',options:{...options,sides:{insideH:true,insideV:true},preserveUnselected:true}});}else{for(const key of id==='all'?[...outer,...inner]:outer)borderDraft[key]=css;borderActions.push({preset:id,options});}}
    preview();
  });
  form.onsubmit=event=>{
    event.preventDefault();try{
      if(!validWorkbookContext(c,true)||c.state.saving||c.state.edits!==edits)throw new Error('Dokumen berubah. Buka kembali Format Cells.');
      const data=new FormData(form),properties={};
      for(const [name,old] of Object.entries(initial)){const value=typeof old==='boolean'?data.has(name):typeof old==='number'?Number(data.get(name)):String(data.get(name));if(value!==old)properties[name]=value;}
      const fill=data.get('fillMode')==='none'?'none':String(data.get('background'));if(fill!==initialFill)properties.background=fill;
      const merge=canMerge&&data.has('merge')!==merged;
      if(Object.keys(properties).length||borderActions.length||merge)mutateWorkbookContext(c,()=>{
        if(merge)WorkbookFormat.merge(c.state.book,c.index,address,merged);
        if(c.axis==='cell')for(const [property,value] of Object.entries(properties))WorkbookFormat.format(c.state.book,c.index,address,property,value);else if(Object.keys(properties).length)WorkbookStructure.formatAxis(c.state.book,c.index,c.axis,c.start,c.end,properties);
        for(const action of borderActions){const axisBorder=c.axis!=='cell'&&['all','none'].includes(action.preset);if(axisBorder)WorkbookStructure.formatAxis(c.state.book,c.index,c.axis,c.start,c.end,{borders:action.preset},action.options);else WorkbookBorders.apply(c.state.book,c.index,address,action.preset,action.options);}
      });
      modal.close();restoreWorkbookFocus();
    }catch(error){document.getElementById('context-format-error').textContent=error.message;}
  };
}
